package run.ikaros.finance; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @Service public class FinanceClassificationService{private final FinanceCategoryRepository categories;private final FinanceTagRepository tags;private final FinanceLedgerAccessService access;public FinanceClassificationService(FinanceCategoryRepository c,FinanceTagRepository t,FinanceLedgerAccessService x){categories=c;tags=t;access=x;}public Mono<CategoryView> createCategory(UUID a,UUID l,CreateCategoryRequest q){return access.requireEditor(a,l).then(categories.save(new FinanceCategoryEntity(null,l,a,q.parentId(),q.name().trim(),q.kind()==null?"EXPENSE":q.kind(),false,null))).map(this::category);}public Flux<CategoryView> categories(UUID a,UUID l){return access.access(a,l).flatMapMany(x->categories.findAllByLedgerIdOrderByNameAsc(l).take(100).map(this::category));}public Mono<TagView> createTag(UUID a,UUID l,CreateTagRequest q){return access.requireEditor(a,l).then(tags.save(new FinanceTagEntity(null,l,a,q.name().trim(),null))).map(this::tag);}public Flux<TagView> tags(UUID a,UUID l){return access.access(a,l).flatMapMany(x->tags.findAllByLedgerIdOrderByNameAsc(l).take(100).map(this::tag));}private CategoryView category(FinanceCategoryEntity x){return new CategoryView(x.id(),x.ledgerId(),x.parentId(),x.name(),x.kind(),x.archived());}private TagView tag(FinanceTagEntity x){return new TagView(x.id(),x.ledgerId(),x.name());}}
